import {escapeHTML as e} from './core.mjs';

// One public source of truth for the Nepocore family. Mark a destination live
// only after its own website, HTTPS and custom domain have been checked.
export const networkSites = [
  {id:'tools',name:'Nepocore Tools',url:'https://nepocore.com/',status:'live',focus:'Everyday browser tools',description:'The main Nepocore website: free calculators, image and PDF tools, study utilities and printable worksheets.',fallback:'./tools/'},
  {id:'resume',name:'Nepocore Resume',url:'https://resume.nepocore.com/',status:'live',focus:'Resumes and cover letters',description:'The dedicated professional resume builder: 24 templates, a live editor, photo controls, cover letters and free PDF and Word exports.',fallback:'./tools/resume-builder/'},
  {id:'nepal',name:'Nepocore Nepal',url:'https://nepal.nepocore.com/',status:'planned',focus:'Everyday utilities for Nepalis',description:'A planned home for Nepali Unicode typing, BS/AD dates and local document templates.',fallback:'./categories/nepal/'},
  {id:'creator',name:'Nepocore Creator',url:'https://creator.nepocore.com/',status:'planned',focus:'Tools for content creators',description:'A planned workspace for caption styling, thumbnail layouts, video safe zones and content planning.',fallback:'./categories/creators/'},
  {id:'pdf',name:'Nepocore PDF',url:'https://pdf.nepocore.com/',status:'planned',focus:'A focused PDF workspace',description:'A planned workspace for merging, splitting, compressing, annotating and organizing PDFs.',fallback:'./categories/pdf/'},
  {id:'qr',name:'Nepocore QR',url:'https://qr.nepocore.com/',status:'planned',focus:'QR codes for everyday sharing',description:'A planned QR studio for Wi-Fi, contacts, menus and events, with printable designs.',fallback:'./tools/qr-code/'},
  {id:'worksheets',name:'Nepocore Worksheets',url:'https://worksheets.nepocore.com/',status:'planned',focus:'Practice sheets for parents and teachers',description:'A planned dedicated site for math, spelling and handwriting worksheets with answer keys.',fallback:'./worksheets/'},
  {id:'typing',name:'Nepocore Typing',url:'https://typing.nepocore.com/',status:'planned',focus:'English and Nepali typing practice',description:'A planned site for typing lessons, speed tests, accuracy feedback and personal progress.',fallback:'./tools/typing-test/'},
  {id:'earnmoneyonline',name:'Nepocore Earn Money Online',url:'https://earnmoneyonline.nepocore.com/',status:'planned',focus:'Practical online work and business guides',description:'A planned publication about freelancing, online work and realistic business ideas. No income or wealth is guaranteed.',fallback:'./categories/business/'},
  {id:'fitness',name:'Nepocore Fitness',url:'https://fitness.nepocore.com/',status:'planned',focus:'Fitness and nutrition planning',description:'A planned fitness and nutrition planning site. Features, suitability and professional review are not yet established.',fallback:'./categories/health/'},
  {id:'freeresources',name:'Nepocore Free Resources',url:'https://freeresources.nepocore.com/',status:'planned',focus:'A directory of useful free resources',description:'A planned curated directory of open-source projects, free courses, apps, software and legally available books.',fallback:'./resources/'}
];
export const resumeSite = networkSites.find(site=>site.id==='resume');
export const preferredToolURL = id => ['resume-builder','cover-letter'].includes(id) && resumeSite.status==='live' ? resumeSite.url + (id==='cover-letter'?'builder/?section=cover':'') : null;
export function dedicatedToolHTML(id){const url=preferredToolURL(id);return url?`<aside class="dedicated-tool"><div><span class="eyebrow">NEPOCORE RESUME / THE DEDICATED STUDIO</span><h2>More room for your next chapter.</h2><p>Use our full resume and cover-letter builder with 24 templates, photo controls, live pages and PDF or Word downloads.</p></div><a class="btn primary" href="${e(url)}">Open resume.nepocore.com ↗</a></aside>`:'';}
